1	package txsaga
2	
3	import (
4		"context"
5		"strings"
6		"sync"
7		"time"
8	)
9	
10	// ValidateDefinition 校验 Saga 定义，非法时返回 ErrInvalidDefinition（可 errors.Is）。
11	// 规则：名称非空、至少一个步骤、每个步骤名非空且不重复、每个步骤都提供正向动作。
12	func ValidateDefinition(d Definition) error {
13		if strings.TrimSpace(d.Name) == "" {
14			return ErrInvalidDefinition
15		}
16		if len(d.Steps) == 0 {
17			return ErrInvalidDefinition
18		}
19		seen := make(map[string]struct{}, len(d.Steps))
20		for _, st := range d.Steps {
21			if strings.TrimSpace(st.Name) == "" || st.Action == nil {
22				return ErrInvalidDefinition
23			}
24			if _, dup := seen[st.Name]; dup {
25				return ErrInvalidDefinition
26			}
27			seen[st.Name] = struct{}{}
28		}
29		return nil
30	}
31	
32	// Engine 在给定 Store 上执行 Saga。零值不可用，请用 NewEngine 创建。
33	type Engine struct {
34		store Store
35	
36		// 同执行身份的进程内串行化，避免并发调用重复进入同一未确认动作。
37		locksMu sync.Mutex
38		locks   map[string]*sync.Mutex
39	
40		// now 为可注入时钟；生产使用 time.Now。
41		now func() time.Time
42	}
43	
44	// NewEngine 创建基于 store 的编排引擎。
45	func NewEngine(store Store) *Engine {
46		return &Engine{store: store, locks: make(map[string]*sync.Mutex), now: time.Now}
47	}
48	
49	func (e *Engine) identityLock(businessKey, idempotencyKey string) *sync.Mutex {
50		key := businessKey + "\x00" + idempotencyKey
51		e.locksMu.Lock()
52		m, ok := e.locks[key]
53		if !ok {
54			m = &sync.Mutex{}
55			e.locks[key] = m
56		}
57		e.locksMu.Unlock()
58		return m
59	}
60	
61	type execView struct {
62		state   *ExecutionState
63		payload any
64	}
65	
66	func (v execView) BusinessKey() string    { return v.state.BusinessKey }
67	func (v execView) SagaName() string       { return v.state.SagaName }
68	func (v execView) IdempotencyKey() string { return v.state.IdempotencyKey }
69	func (v execView) Payload() any           { return v.payload }
70	
71	func (v execView) SucceededSteps() []string {
72		var names []string
73		for _, st := range v.state.Steps {
74			if st.Status == StepResultSucceeded {
75				names = append(names, st.Name)
76			}
77		}
78		return names
79	}
80	
81	// Execute 按 Definition 执行一次 Saga 请求。
82	//
83	// 执行身份由业务键、Saga 定义与外部幂等键共同确定：
84	//   - 新身份：创建执行并顺序执行未完成步骤；
85	//   - 同身份重试：不重复执行已确认成功的正向步骤或补偿步骤；
86	//     结果未确认的步骤允许被重新调用，重入次数累计在对应步骤的 Attempts，
87	//     动作自身须遵守幂等契约；
88	//   - 已到达终态：直接返回固定的终态结果，不再调用任何动作，也不再追加事件；
89	//   - 同业务键绑定不同定义：返回 ErrDefinitionConflict；
90	//   - 非法定义或缺失业务键/幂等键：返回 ErrInvalidDefinition。
91	//
92	// 每一步确认后，状态与对应 Outbox 事件在同一个 Store 事务中原子提交，
93	// 然后才执行下一步。正向动作失败即停止推进，仅逆序补偿此前确认成功的步骤；
94	// 任一补偿报错则固定为 compensation_failed 终态。
95	func (e *Engine) Execute(ctx context.Context, def Definition, req ExecutionRequest) (Result, error) {
96		if err := ValidateDefinition(def); err != nil {
97			return Result{}, err
98		}
99		if strings.TrimSpace(req.BusinessKey) == "" || strings.TrimSpace(req.IdempotencyKey) == "" {
100			return Result{}, ErrInvalidDefinition
101		}
102		fp := fingerprint(def)
103	
104		mu := e.identityLock(req.BusinessKey, req.IdempotencyKey)
105		mu.Lock()
106		defer mu.Unlock()
107	
108		for {
109			if err := ctx.Err(); err != nil {
110				return Result{}, err
111			}
112			snap, err := e.store.LoadSnapshot(ctx, req.BusinessKey, req.IdempotencyKey)
113			if err != nil {
114				return Result{}, err
115			}
116			if snap.Bound && snap.Binding.Fingerprint != fp {
117				return Result{}, ErrDefinitionConflict
118			}
119			st := snap.State
120			if st == nil {
121				if err := e.createExecution(ctx, def, fp, req); err != nil {
122					return Result{}, err
123				}
124				continue
125			}
126			if st.Fingerprint != fp {
127				return Result{}, ErrDefinitionConflict
128			}
129			if st.Terminal() {
130				return toResult(st), nil
131			}
132	
133			switch st.Status {
134			case StatusRunning:
135				advanced, err := e.advanceForward(ctx, def, req, st)
136				if err != nil {
137					return Result{}, err
138				}
139				if !advanced {
140					// 所有步骤均已确认成功，重新读取以取得 completed 终态。
141					snap2, err := e.store.LoadSnapshot(ctx, req.BusinessKey, req.IdempotencyKey)
142					if err != nil {
143						return Result{}, err
144					}
145					return toResult(snap2.State), nil
146				}
147			case StatusCompensating:
148				done, err := e.advanceCompensation(ctx, def, req, st)
149				if err != nil {
150					return Result{}, err
151				}
152				if done {
153					return e.finishFailed(ctx, req)
154				}
155			default:
156				return Result{}, ErrInvalidDefinition
157			}
158		}
159	}
160	
161	// createExecution 在一个原子事务中建立执行状态并追加 started 事件。
162	func (e *Engine) createExecution(ctx context.Context, def Definition, fp string, req ExecutionRequest) error {
163		return e.store.Commit(ctx, req.BusinessKey, req.IdempotencyKey, func(tx Tx) error {
164			if b, ok := tx.Binding(); ok && b.Fingerprint != fp {
165				return ErrDefinitionConflict
166			}
167			if tx.State() != nil {
168				return nil // 并发情况下已由其它调用建立，直接沿用
169			}
170			steps := make([]StepState, len(def.Steps))
171			for i, s := range def.Steps {
172				steps[i] = StepState{Name: s.Name}
173			}
174			tx.Create(&ExecutionState{
175				SagaName:    def.Name,
176				Fingerprint: fp,
177				Status:      StatusRunning,
178				Steps:       steps,
179				Payload:     req.Payload,
180			})
181			tx.AppendEvent(EventExecutionStarted, EventPayload{
182				SagaName:       def.Name,
183				IdempotencyKey: req.IdempotencyKey,
184				Status:         StatusRunning,
185			})
186			return nil
187		})
188	}
189	
190	// advanceForward 执行下一个未完成的正向步骤，在事务外调用动作，再把
191	// 成功/失败结果与事件原子提交。返回 false 表示已无待执行步骤。
192	func (e *Engine) advanceForward(ctx context.Context, def Definition, req ExecutionRequest, st *ExecutionState) (bool, error) {
193		idx := -1
194		for i := range st.Steps {
195			if st.Steps[i].Status == "" {
196				idx = i
197				break
198			}
199		}
200		if idx < 0 {
201			return false, nil
202		}
203		step := def.Steps[idx]
204	
205		// Attempts 记录该步骤动作的实际调用次数；同身份重试已确认步骤时不会自增。
206		// 未确认结果的步骤被重新调用时该值增大，调用方据此判断是否发生重复处理。
207		st.Steps[idx].Attempts++
208		st.Steps[idx].StartedAt = e.now()
209		if err := ctx.Err(); err != nil {
210			return false, err
211		}
212		actionErr := step.Action(ctx, execView{state: st, payload: req.Payload})
213		if err := ctx.Err(); err != nil {
214			// 调用方取消：不把取消解释为业务失败，未确认的步骤留待后续同身份重试。
215			return false, err
216		}
217		finishedAt := e.now()
218	
219		err := e.store.Commit(ctx, req.BusinessKey, req.IdempotencyKey, func(tx Tx) error {
220			cur := tx.State()
221			if cur == nil || cur.Terminal() {
222				return nil // 状态已被其它路径推进，本次结果丢弃
223			}
224			cs := &cur.Steps[idx]
225			cs.Attempts = st.Steps[idx].Attempts
226			cs.StartedAt = st.Steps[idx].StartedAt
227			cs.FinishedAt = finishedAt
228	
229			if actionErr == nil {
230				cs.Status = StepResultSucceeded
231				cs.LastError = ""
232				succeeded := succeededNames(cur)
233				if idx == len(cur.Steps)-1 {
234					cur.Status = StatusCompleted
235					tx.AppendEvent(EventStepSucceeded, stepEvent(def, req, step.Name, StatusCompleted, succeeded))
236					tx.AppendEvent(EventExecutionCompleted, EventPayload{
237						SagaName:       def.Name,
238						IdempotencyKey: req.IdempotencyKey,
239						Status:         StatusCompleted,
240						SucceededSteps: succeeded,
241					})
242				} else {
243					cur.Status = StatusRunning
244					tx.AppendEvent(EventStepSucceeded, stepEvent(def, req, step.Name, StatusRunning, succeeded))
245				}
246				return nil
247			}
248	
249			errMsg := actionErr.Error()
250			cs.Status = StepResultFailed
251			cs.LastError = errMsg
252			cur.FailedStep = step.Name
253			cur.FailureReason = errMsg
254			cur.Status = StatusCompensating
255			tx.AppendEvent(EventStepFailed, EventPayload{
256				SagaName:       def.Name,
257				IdempotencyKey: req.IdempotencyKey,
258				Step:           step.Name,
259				Status:         StatusCompensating,
260				Reason:         errMsg,
261				SucceededSteps: succeededNames(cur),
262			})
263			return nil
264		})
265		return err == nil, err
266	}
267	
268	// advanceCompensation 逆序补偿下一个已确认成功的步骤。
269	// 返回 done=true 表示已无待补偿步骤，调用方应把执行收束为 failed 终态。
270	// 补偿动作返回错误时，执行在同一事务中固定为 compensation_failed 终态。
271	func (e *Engine) advanceCompensation(ctx context.Context, def Definition, req ExecutionRequest, st *ExecutionState) (bool, error) {
272		idx := -1
273		for i := len(st.Steps) - 1; i >= 0; i-- {
274			if st.Steps[i].Status == StepResultSucceeded {
275				idx = i
276				break
277			}
278		}
279		if idx < 0 {
280			return true, nil
281		}
282		step := def.Steps[idx]
283	
284		var compErr error
285		calledCompensation := step.Compensate != nil
286		if calledCompensation {
287			st.Steps[idx].CompensationAttempts++
288			if err := ctx.Err(); err != nil {
289				return false, err
290			}
291			compErr = step.Compensate(ctx, execView{state: st, payload: req.Payload})
292			if err := ctx.Err(); err != nil {
293				return false, err
294			}
295		}
296		var compensatedAt time.Time
297		if calledCompensation {
298			compensatedAt = e.now()
299		}
300	
301		err := e.store.Commit(ctx, req.BusinessKey, req.IdempotencyKey, func(tx Tx) error {
302			cur := tx.State()
303			if cur == nil || cur.Terminal() {
304				return nil
305			}
306			cs := &cur.Steps[idx]
307			if calledCompensation {
308				cs.CompensationAttempts = st.Steps[idx].CompensationAttempts
309				cs.CompensatedAt = compensatedAt
310			}
311	
312			if compErr == nil {
313				cs.Status = StepResultCompensated
314				cs.LastError = ""
315				cur.Status = StatusCompensating
316				tx.AppendEvent(EventStepCompensated, EventPayload{
317					SagaName:       def.Name,
318					IdempotencyKey: req.IdempotencyKey,
319					Step:           step.Name,
320					Status:         StatusCompensating,
321				})
322				return nil
323			}
324	
325			errMsg := compErr.Error()
326			cs.Status = StepResultCompensationFailed
327			cs.LastError = errMsg
328			cur.FailedCompensationStep = step.Name
329			cur.CompensationError = errMsg
330			cur.Status = StatusCompensationFailed
331			tx.AppendEvent(EventStepCompensationFailed, EventPayload{
332				SagaName:       def.Name,
333				IdempotencyKey: req.IdempotencyKey,
334				Step:           step.Name,
335				Status:         StatusCompensationFailed,
336				Reason:         errMsg,
337				Attempt:        cs.CompensationAttempts,
338			})
339			tx.AppendEvent(EventCompensationFailed, EventPayload{
340				SagaName:       def.Name,
341				IdempotencyKey: req.IdempotencyKey,
342				Step:           step.Name,
343				Status:         StatusCompensationFailed,
344				Reason:         errMsg,
345			})
346			return nil
347		})
348		if err != nil {
349			return false, err
350		}
351		return false, nil
352	}
353	
354	// finishFailed 在补偿全部完成后把执行收束为 failed 终态并返回结果。
355	func (e *Engine) finishFailed(ctx context.Context, req ExecutionRequest) (Result, error) {
356		err := e.store.Commit(ctx, req.BusinessKey, req.IdempotencyKey, func(tx Tx) error {
357			cur := tx.State()
358			if cur == nil || cur.Terminal() {
359				return nil
360			}
361			cur.Status = StatusFailed
362			tx.AppendEvent(EventExecutionFailed, EventPayload{
363				SagaName:       cur.SagaName,
364				IdempotencyKey: req.IdempotencyKey,
365				Status:         StatusFailed,
366				Step:           cur.FailedStep,
367				Reason:         cur.FailureReason,
368			})
369			return nil
370		})
371		if err != nil {
372			return Result{}, err
373		}
374		snap, err := e.store.LoadSnapshot(ctx, req.BusinessKey, req.IdempotencyKey)
375		if err != nil {
376			return Result{}, err
377		}
378		return toResult(snap.State), nil
379	}
380	
381	func succeededNames(st *ExecutionState) []string {
382		var names []string
383		for _, s := range st.Steps {
384			if s.Status == StepResultSucceeded {
385				names = append(names, s.Name)
386			}
387		}
388		return names
389	}
390	
391	func stepEvent(def Definition, req ExecutionRequest, step, status string, succeeded []string) EventPayload {
392		return EventPayload{
393			SagaName:       def.Name,
394			IdempotencyKey: req.IdempotencyKey,
395			Step:           step,
396			Status:         status,
397			SucceededSteps: succeeded,
398		}
399	}
400	
401	func toResult(st *ExecutionState) Result {
402		outcomes := make([]StepOutcome, len(st.Steps))
403		for i, s := range st.Steps {
404			r := s.Status
405			if r == "" {
406				r = StepResultPending
407			}
408			outcomes[i] = StepOutcome{
409				Name:                 s.Name,
410				Result:               r,
411				Attempts:             s.Attempts,
412				CompensationAttempts: s.CompensationAttempts,
413				Error:                s.LastError,
414				StartedAt:            s.StartedAt,
415				FinishedAt:           s.FinishedAt,
416			}
417		}
418		return Result{
419			BusinessKey:            st.BusinessKey,
420			SagaName:               st.SagaName,
421			IdempotencyKey:         st.IdempotencyKey,
422			Status:                 st.Status,
423			FailureReason:          st.FailureReason,
424			CompensationError:      st.CompensationError,
425			FailedStep:             st.FailedStep,
426			FailedCompensationStep: st.FailedCompensationStep,
427			Steps:                  outcomes,
428			Terminal:               st.Terminal(),
429		}
430	}
431	
432	// GetResult 查询某执行身份的当前结果，不执行任何动作。
433	// 未知执行身份（或 sagaName 与该执行的定义名不符）返回 ErrExecutionNotFound。
434	func (e *Engine) GetResult(ctx context.Context, sagaName, businessKey, idempotencyKey string) (Result, error) {
435		if strings.TrimSpace(sagaName) == "" || strings.TrimSpace(businessKey) == "" || strings.TrimSpace(idempotencyKey) == "" {
436			return Result{}, ErrInvalidDefinition
437		}
438		snap, err := e.store.LoadSnapshot(ctx, businessKey, idempotencyKey)
439		if err != nil {
440			return Result{}, err
441		}
442		if snap.State == nil || snap.State.SagaName != sagaName {
443			return Result{}, ErrExecutionNotFound
444		}
445		return toResult(snap.State), nil
446	}
