11	)
12	
13	// recorder 记录各动作被调用的顺序与次数，供断言编排顺序和是否重复处理。
14	type recorder struct {
15		mu    sync.Mutex
16		calls []string
17	}
18	
19	func (r *recorder) call(name string) {
20		r.mu.Lock()
21		defer r.mu.Unlock()
22		r.calls = append(r.calls, name)
23	}
24	
25	func (r *recorder) count(name string) int {
26		r.mu.Lock()
27		defer r.mu.Unlock()
28		n := 0
29		for _, c := range r.calls {
30			if c == name {
31				n++
32			}
33		}
34		return n
35	}
36	
37	func (r *recorder) snapshot() []string {
38		r.mu.Lock()
39		defer r.mu.Unlock()
40		return append([]string(nil), r.calls...)
41	}
42	
43	func threeStepDef(rec *recorder, failStep string, failComp string) Definition {
44		step := func(name string) Step {
45			return Step{
46				Name: name,
47				Action: func(_ context.Context, _ ExecutionView) error {
48					rec.call("do:" + name)
49					if name == failStep {
50						return errors.New("boom-" + name)
51					}
52					return nil
53				},
54				Compensate: func(_ context.Context, _ ExecutionView) error {
55					rec.call("undo:" + name)
56					if name == failComp {
57						return errors.New("comp-boom-" + name)
58					}
59					return nil
60				},
61			}
62		}
63		return Definition{
64			Name:    "order-saga",
65			Version: "v1",
66			Steps:   []Step{step("reserve"), step("charge"), step("ship")},
67		}
68	}
69	
70	func TestExecuteSuccess(t *testing.T) {
71		store := NewMemoryStore()
72		eng := NewEngine(store)
73		rec := &recorder{}
74		def := threeStepDef(rec, "", "")
75	
76		res, err := eng.Execute(context.Background(), def, ExecutionRequest{
77			BusinessKey:    "order-1",
78			IdempotencyKey: "req-1",
79			Payload:        map[string]int{"amount": 100},
80		})
81		if err != nil {
82			t.Fatalf("Execute: %v", err)
83		}
84		if res.Status != StatusCompleted || !res.Terminal {
85			t.Fatalf("status=%s terminal=%v, want completed/terminal", res.Status, res.Terminal)
86		}
87		if got := rec.snapshot(); fmt.Sprint(got) != "[do:reserve do:charge do:ship]" {
88			t.Fatalf("calls = %v", got)
89		}
90		for _, so := range res.Steps {
91			if so.Result != StepResultSucceeded || so.Attempts != 1 {
92				t.Fatalf("step %s = %+v", so.Name, so)
93			}
94			if so.StartedAt.IsZero() || so.FinishedAt.Before(so.StartedAt) {
95				t.Fatalf("step %s bad timestamps: %v %v", so.Name, so.StartedAt, so.FinishedAt)
96			}
97		}
98	
99		// 事件顺序：started -> 每步 succeeded -> completed，且与状态同事务可见。
100		events, err := store.ClaimPendingEvents(context.Background(), 100)
101		if err != nil {
102			t.Fatal(err)
103		}
104		wantTypes := []string{
105			EventExecutionStarted,
106			EventStepSucceeded, EventStepSucceeded, EventStepSucceeded,
107			EventExecutionCompleted,
108		}
109		if len(events) != len(wantTypes) {
110			t.Fatalf("events=%d want=%d", len(events), len(wantTypes))
111		}
112		for i, ev := range events {
113			if ev.Type != wantTypes[i] {
114				t.Fatalf("event[%d]=%s want %s", i, ev.Type, wantTypes[i])
115			}
116			if ev.ID == "" || ev.BusinessKey != "order-1" || ev.OccurredAt.IsZero() {
117				t.Fatalf("event metadata incomplete: %+v", ev)
118			}
119			if ev.Deliveries() != 1 {
120				t.Fatalf("deliveries=%d want 1", ev.Deliveries())
121			}
122		}
123	}
124	
125	func TestExecuteForwardFailureCompensatesInReverse(t *testing.T) {
126		store := NewMemoryStore()
127		eng := NewEngine(store)
128		rec := &recorder{}
129		// charge 失败：reserve 已确认成功需补偿；ship 从未执行，不得补偿。
130		def := threeStepDef(rec, "charge", "")
131	
132		res, err := eng.Execute(context.Background(), def, ExecutionRequest{
133			BusinessKey:    "order-2",
134			IdempotencyKey: "req-2",
135		})
136		if err != nil {
137			t.Fatalf("Execute: %v", err)
138		}
139		if res.Status != StatusFailed || !res.Terminal {
140			t.Fatalf("status=%s want failed", res.Status)
141		}
142		if res.FailedStep != "charge" || res.FailureReason != "boom-charge" {
143			t.Fatalf("failure info: %+v", res)
144		}
145		if got := rec.snapshot(); fmt.Sprint(got) != "[do:reserve do:charge undo:reserve]" {
146			t.Fatalf("calls = %v, want forward then reverse compensation only", got)
147		}
148		results := map[string]string{}
149		for _, so := range res.Steps {
150			results[so.Name] = so.Result
151		}
152		if results["reserve"] != StepResultCompensated ||
153			results["charge"] != StepResultFailed ||
154			results["ship"] != StepResultPending {
155			t.Fatalf("step results = %v", results)
156		}
157	
158		events, _ := store.ClaimPendingEvents(context.Background(), 100)
159		wantTypes := []string{
160			EventExecutionStarted,
161			EventStepSucceeded, // reserve
162			EventStepFailed,    // charge
163			EventStepCompensated,
164			EventExecutionFailed,
165		}
166		if len(events) != len(wantTypes) {
167			t.Fatalf("events=%d want=%d (%v)", len(events), len(wantTypes), eventTypes(events))
168		}
169		for i, ev := range events {
170			if ev.Type != wantTypes[i] {
171				t.Fatalf("event[%d]=%s want %s, all=%v", i, ev.Type, wantTypes[i], eventTypes(events))
172			}
173		}
174	}
175	
176	func TestCompensationFailureIsTerminalAndStable(t *testing.T) {
177		store := NewMemoryStore()
