467		if res.Claimed != 2 || res.Failed != 2 || res.Delivered != 0 {
468			t.Fatalf("res=%+v", res)
469		}
470		select {
471		case <-publishCalled:
472			t.Fatal("Publish must not be called when ctx canceled before publish")
473		default:
474		}
475	
476		// 立即 Nack 使其无需等待租约即可重投。
477		res, err = relay.DeliverOnce(context.Background())
478		if err != nil {
479			t.Fatal(err)
480		}
481		if res.Claimed != 2 || res.Delivered != 2 {
482			t.Fatalf("res=%+v", res)
483		}
484	}
485	
486	func TestRelayLeaseCancelDuringPublishFollowsPublishResult(t *testing.T) {
487		// 情形一：Publish 期间取消，但 Publish 返回 nil —— 照常 Ack。
488		store, _, _ := leasedTestStore(t, 1)
489		started := make(chan struct{})
490		release := make(chan struct{})
491		pub := PublisherFunc(func(ctx context.Context, _ Event) error {
492			close(started)
493			<-release
494			// 即使 ctx 已取消，Publish 的业务结论是成功。
495			return nil
496		})
497		relay := NewRelay(store, pub, WithClaimLease(time.Minute))
498		ctx, cancel := context.WithCancel(context.Background())
499		done := make(chan struct{})
500		var res RelayResult
501		var err error
502		go func() {
503			res, err = relay.DeliverOnce(ctx)
504			close(done)
505		}()
506		<-started
507		cancel()
508		close(release)
509		<-done
510		if err != nil {
511			t.Fatal(err)
512		}
513		if res.Delivered != 1 || store.TotalEvents() != 0 {
514			t.Fatalf("successful publish despite cancel must ack: res=%+v remaining=%d", res, store.TotalEvents())
515		}
516	
517		// 情形二：Publish 期间取消且 Publish 返回 error —— 照常 Nack，立即可重领。
518		store2, _, _ := leasedTestStore(t, 1)
519		started2 := make(chan struct{})
520		release2 := make(chan struct{})
521		var once2 sync.Once
522		pub2 := PublisherFunc(func(context.Context, Event) error {
523			once2.Do(func() {
524				close(started2)
525				<-release2
526			})
527			return errors.New("publish failed during shutdown")
528		})
529		relay2 := NewRelay(store2, pub2, WithClaimLease(time.Minute))
530		ctx2, cancel2 := context.WithCancel(context.Background())
531		done2 := make(chan struct{})
532		var res2 RelayResult
533		go func() {
534			res2, _ = relay2.DeliverOnce(ctx2)
535			close(done2)
536		}()
537		<-started2
538		cancel2()
539		close(release2)
540		<-done2
541		if res2.Failed != 1 {
542			t.Fatalf("failed publish during cancel must nack: %+v", res2)
543		}
544		next, err := relay2.DeliverOnce(context.Background())
545		if err != nil {
546			t.Fatal(err)
547		}
548		if next.Claimed != 1 {
549			t.Fatalf("nacked event must be immediately reclaimable: %+v", next)
550		}
551	}
552	
553	func TestRelayToleratesStaleClaimAfterTakeover(t *testing.T) {
554		store, clk, _ := leasedTestStore(t, 1)
555		takeover := &staleNackStore{MemoryStore: store}
556		pub := PublisherFunc(func(context.Context, Event) error {
557			return errors.New("downstream unavailable")
558		})
559		relay := NewRelay(takeover, pub, WithClaimLease(time.Minute))
560	
561		res, err := relay.DeliverOnce(context.Background())
562		if err != nil {
563			t.Fatalf("relay must swallow ErrStaleClaim: %v", err)
564		}
565		if res.Failed != 1 {
566			t.Fatalf("res=%+v", res)
567		}
568	
569		// 首次 Nack 被判定为 stale（模拟已被接管），事件仍在旧/新租约中；
570		// 到期后由下一轮恢复。
571		clk.advance(time.Minute + time.Second)
572		if store.PendingCount() != 1 {
573			t.Fatalf("stale nack must not make event reclaimable early: %d", store.PendingCount())
574		}
575	}
576	
577	// plainStore 只实现 Store，刻意不实现 ClaimLeaseStore。
578	type plainStore struct {
579		inner *MemoryStore
580	}
581	
582	func (s *plainStore) LoadSnapshot(ctx context.Context, bk, ik string) (Snapshot, error) {
583		return s.inner.LoadSnapshot(ctx, bk, ik)
584	}
585	func (s *plainStore) Commit(ctx context.Context, bk, ik string, fn func(Tx) error) error {
586		return s.inner.Commit(ctx, bk, ik, fn)
587	}
588	func (s *plainStore) ClaimPendingEvents(ctx context.Context, max int) ([]*Event, error) {
589		return s.inner.ClaimPendingEvents(ctx, max)
590	}
591	func (s *plainStore) AckEvent(ctx context.Context, id string) error {
592		return s.inner.AckEvent(ctx, id)
593	}
594	func (s *plainStore) NackEvent(ctx context.Context, id string) error {
595		return s.inner.NackEvent(ctx, id)
596	}
597	
598	var _ Store = (*plainStore)(nil)
599	
600	func TestRelayLeaseUnsupportedByStore(t *testing.T) {
601		store, _, _ := leasedTestStore(t, 1)
602		plain := &plainStore{inner: store}
603		pub := PublisherFunc(func(context.Context, Event) error { return nil })
604		relay := NewRelay(plain, pub, WithClaimLease(time.Minute))
605	
606		_, err := relay.DeliverOnce(context.Background())
607		if !errors.Is(err, ErrClaimLeaseUnsupported) {
608			t.Fatalf("DeliverOnce err=%v want ErrClaimLeaseUnsupported", err)
609		}
610		// Run 原样退出，不重试、不等待。
611		done := make(chan error, 1)
612		go func() { done <- relay.Run(context.Background()) }()
613		select {
614		case err := <-done:
615			if !errors.Is(err, ErrClaimLeaseUnsupported) {
616				t.Fatalf("Run err=%v want ErrClaimLeaseUnsupported", err)
617			}
618		case <-time.After(time.Second):
619			t.Fatal("Run must return immediately when lease unsupported")
620		}
621	
622		// 事件未被领取，默认路径仍可正常投递。
623		defaultRelay := NewRelay(plain, pub)
624		res, err := defaultRelay.DeliverOnce(context.Background())
625		if err != nil {
626			t.Fatal(err)
627		}
628		if res.Claimed != 1 || res.Delivered != 1 {
629			t.Fatalf("default path after unsupported lease: %+v", res)
630		}
631	}
632	
633	func TestWithClaimLeaseNonPositiveIsIgnored(t *testing.T) {
634		pub := PublisherFunc(func(context.Context, Event) error { return nil })
635	
636		for _, d := range []time.Duration{0, -time.Second, -time.Nanosecond} {
637			store, _, _ := leasedTestStore(t, 1)
638			plain := &plainStore{inner: store}
639			relay := NewRelay(plain, pub, WithClaimLease(d))
640			res, err := relay.DeliverOnce(context.Background())
641			if err != nil {
642				t.Fatalf("ttl=%v: %v", d, err)
643			}
644			if res.Claimed != 1 || res.Delivered != 1 || store.TotalEvents() != 0 {
645				t.Fatalf("ttl=%v must keep default behavior: %+v", d, res)
646			}
647		}
648	}
649	
650	// errCrashAck 模拟 worker 在 Ack 调用时崩溃/存储暂不可用。
651	var errCrashAck = errors.New("ack storage unavailable")
652	
653	type crashAckStore struct {
654		*MemoryStore
655	}
656	
657	func (s *crashAckStore) AckLeasedEvent(ctx context.Context, eventID, claimID string) error {
658		return errCrashAck
659	}
660	
661	// staleNackStore 让第一次 NackLeasedEvent 返回 ErrStaleClaim，
662	// 模拟租约到期后事件已被新领取者接管。
663	type staleNackStore struct {
664		*MemoryStore
665		done bool
666	}
667	
668	func (s *staleNackStore) NackLeasedEvent(ctx context.Context, eventID, claimID string) error {
669		if !s.done {
670			s.done = true
671			return ErrStaleClaim
672		}
673		return s.MemoryStore.NackLeasedEvent(ctx, eventID, claimID)
674	}
