		t.Fatal(err)
	}
	if len(page.Records) != 3 {
		t.Fatalf("records=%d want 3", len(page.Records))
	}
	for i, r := range page.Records {
		if r.ID != ids[i] {
			t.Fatalf("record[%d]=%s want %s: lease/nack/ack must not reorder history",
				i, r.ID, ids[i])
		}
	}
