					t.Errorf("commit: %v",
						err)
					return
				}
			}
		}()
	}

	// 与追加并发翻页：每一页都必须是内部有序、无重复、不超过上限的一致快照。
	stop := make(chan struct{})
	go func() {
		wg2.Wait()
		close(stop)
	}()
	readerDone := make(chan struct{})
	go func() {
		defer close(readerDone)
