			case <-stop:
				return
			default:
			}
			p, err := store.ListEvents(ctx, EventHistoryQuery{
				SagaName: "c", BusinessKey: "bk", IdempotencyKey: "ik", Limit: 7,
			})
			if err != nil {
				t.Errorf("concurrent read: %v", err)
				return
			}
