			var prev uint64
			for i, r := range p.Records {
				seq := eventSeq(r.ID)
				if seen[seq] {
					t.Errorf("duplicate id within page: %s", r.ID)
				}
				seen[seq] = true
				if i > 0 && seq <= prev {
					t.Errorf("page not in append order: %d after %d", seq, prev)
				}
				prev = seq
			}
		}
	}()
