	// 全链中每个发生时间都必须成组完整出现，不得观察到半组。
	groups := map[time.Time]int{}
	for _, r := range all {
		groups[r.OccurredAt]++
	}
	for at, n := range groups {
		if n != perCommit {
			t.Fatalf("non-atomic batch at %v: %d of %d events visible", at, n, perCommit)
		}
	}
}

